4.5.3 基于VC#的程序流程(2)

使用后期绑定时的程序流程如下所示。不需要进行本产品的参照设定。但在调用Method时，请事先声明在参
   数中指定的参数数组。该程序是获取工件坐标系偏置的示例程序。

//EZSocket对象的声明
    Type objClassType = Type.GetTypeFromProgID("EZNcAut.DispEZNcCommunication");
    //EZSocket对象的生成
    object objEZNC_Late = Activator.CreateInstance(objClassType);

//局变量声明
    object Ret = 0;
    double pdoffset = 0;

//相对于参数的数组的声明
    object[] tcpip_arg ={"192.168.1.1",683};
    object[] open_arg = {9, 1, 10, "EZNC_LOCALHOST"};
    object[] getwork_arg = { 1, 54, out pdoffset};
    object[] close_arg = { };

//通信打开
    Ret = objEZNC_Late.GetType().InvokeMember("SetTCPIPProtocol",
                                BindingFlags.InvokeMethod, null, objEZNC_Late, tcpip_arg);
    Ret = objEZNC_Late.GetType().InvokeMember("Open3", BindingFlags.InvokeMethod, null, objEZNC_Late, open_arg);

//获取工件坐标系偏置
    Ret   =   objEZNC_Late.GetType().InvokeMember("Tool_GetToolWorkOffSet",
                                BindingFlags.InvokeMethod, null, objEZNC_Late, getwork_arg);

//通信关闭
    Ret = objEZNC_Late.GetType().InvokeMember("Close", BindingFlags.InvokeMethod, null, objEZNC_Late, close_arg);

//释放对象
    objEZNC_Late = null;

* 本示例程序按照VC# 7.0或更高版本的规格。
   若使用VC#7.0或更早版本，可能需要使用InvokeMember()的ParameterModifier参数来参照输出数据。

